  # Defines the GitHubV3REST SDK type.
  class GitHubV3REST
    attr_reader :meta, :security_advisories, :agent_automations, :agent_tasks, :apps, :classroom,
                :codes_of_conduct, :credentials, :emojis, :actions, :oidc, :code_security, :copilot,
                :dependabot, :activity, :gists, :gitignore, :issues, :licenses, :markdown, :orgs,
                :billing, :agents, :campaigns, :code_scanning, :codespaces, :copilot_spaces, :packages,
                :interactions, :migrations, :private_registries, :projects, :repos, :secret_scanning,
                :hosted_compute, :teams, :rate_limit, :checks, :code_quality, :reactions,
                :dependency_graph, :git, :pulls, :search, :users

    SUB_NAMESPACES = {
      meta: MetaNamespace,
      security_advisories: SecurityAdvisoriesNamespace,
      agent_automations: AgentAutomationsNamespace,
      agent_tasks: AgentTasksNamespace,
      apps: AppsNamespace,
      classroom: ClassroomNamespace,
